CREATE TABLE Claim(Claim_Identifier int,Catastrophe_Identifier int,Claim_Description varchar,Claims_Made_Date datetime,Company_Claim_Number varchar,Company_Subclaim_Number varchar,Insurable_Object_Identifier int,Occurrence_Identifier int,Entry_Into_Claims_Made_Program_Date datetime,Claim_Open_Date datetime,Claim_Close_Date datetime,Claim_Reopen_Date datetime,Claim_Status_Code varchar,Claim_Reported_Date datetime,PRIMARY KEY(Claim_Identifier ASC),FOREIGN KEY(Catastrophe_Identifier)REFERENCES Catastrophe(Catastrophe_Identifier),FOREIGN KEY(Claim_Identifier)REFERENCES Claim(Claim_Identifier),FOREIGN KEY(Insurable_Object_Identifier)REFERENCES Insurable_Object(Insurable_Object_Identifier),FOREIGN KEY(Occurrence_Identifier)REFERENCES Occurrence(Occurrence_Identifier));
CREATE TABLE Claim_Amount(Claim_Amount_Identifier bigint,Claim_Identifier int,Claim_Offer_Identifier int,Amount_Type_Code varchar,Event_Date datetime,Claim_Amount decimal(15,2),Insurance_Type_Code char,PRIMARY KEY(Claim_Amount_Identifier ASC),FOREIGN KEY(Claim_Offer_Identifier)REFERENCES Claim_Offer(Claim_Offer_Identifier),FOREIGN KEY(Claim_Identifier)REFERENCES Claim(Claim_Identifier));
CREATE TABLE Loss_Payment(Claim_Amount_Identifier bigint,PRIMARY KEY(Claim_Amount_Identifier ASC),FOREIGN KEY(Claim_Amount_Identifier)REFERENCES Claim_Payment(Claim_Amount_Identifier));
CREATE TABLE Loss_Reserve(Claim_Amount_Identifier bigint,PRIMARY KEY(Claim_Amount_Identifier ASC),FOREIGN KEY(Claim_Amount_Identifier)REFERENCES Claim_Reserve(Claim_Amount_Identifier));
CREATE TABLE Expense_Payment(Claim_Amount_Identifier bigint,PRIMARY KEY(Claim_Amount_Identifier ASC),FOREIGN KEY(Claim_Amount_Identifier)REFERENCES Claim_Payment(Claim_Amount_Identifier));
CREATE TABLE Expense_Reserve(Claim_Amount_Identifier bigint,PRIMARY KEY(Claim_Amount_Identifier ASC),FOREIGN KEY(Claim_Amount_Identifier)REFERENCES Claim_Reserve(Claim_Amount_Identifier));
CREATE TABLE Claim_Coverage(Claim_Identifier int,Effective_Date datetime,Policy_Coverage_Detail_Identifier int,PRIMARY KEY(Claim_Identifier ASC,Effective_Date ASC,Policy_Coverage_Detail_Identifier ASC),FOREIGN KEY(Claim_Identifier)REFERENCES Claim(Claim_Identifier),FOREIGN KEY(Effective_Date,Policy_Coverage_Detail_Identifier)REFERENCES Policy_Coverage_Detail(Effective_Date,Policy_Coverage_Detail_Identifier));
CREATE TABLE Policy_Coverage_Detail(Effective_Date datetime,Policy_Coverage_Detail_Identifier int,Coverage_Identifier int,Insurable_Object_Identifier int,Policy_Identifier int,Coverage_Part_Code varchar,Coverage_Description varchar,Expiration_Date datetime,Coverage_Inclusion_Exclusion_Code char,PRIMARY KEY(Effective_Date ASC,Policy_Coverage_Detail_Identifier ASC),FOREIGN KEY(Insurable_Object_Identifier)REFERENCES Insurable_Object(Insurable_Object_Identifier),FOREIGN KEY(Coverage_Identifier)REFERENCES Coverage(Coverage_Identifier),FOREIGN KEY(Coverage_Part_Code,Policy_Identifier)REFERENCES Policy_Coverage_Part(Coverage_Part_Code,Policy_Identifier));
CREATE TABLE Policy(Policy_Identifier int,Effective_Date datetime,Expiration_Date datetime,Policy_Number varchar,Status_Code varchar,Geographic_Location_Identifier int,PRIMARY KEY(Policy_Identifier ASC),FOREIGN KEY(Geographic_Location_Identifier)REFERENCES Geographic_Location(Geographic_Location_Identifier),FOREIGN KEY(Policy_Identifier)REFERENCES Agreement(Agreement_Identifier));
CREATE TABLE Policy_Amount(Policy_Amount_Identifier bigint,Geographic_Location_Identifier int,Policy_Identifier int,Effective_Date datetime,Amount_Type_Code varchar,Earning_Begin_Date datetime,Earning_End_Date datetime,Policy_Coverage_Detail_Identifier int,Policy_Amount decimal(15,2),Insurable_Object_Identifier int,Insurance_Type_Code char,PRIMARY KEY(Policy_Amount_Identifier ASC),FOREIGN KEY(Effective_Date,Policy_Coverage_Detail_Identifier)REFERENCES Policy_Coverage_Detail(Effective_Date,Policy_Coverage_Detail_Identifier),FOREIGN KEY(Policy_Identifier)REFERENCES Policy(Policy_Identifier),FOREIGN KEY(Geographic_Location_Identifier)REFERENCES Geographic_Location(Geographic_Location_Identifier),FOREIGN KEY(Insurable_Object_Identifier)REFERENCES Insurable_Object(Insurable_Object_Identifier));
CREATE TABLE Agreement_Party_Role(Agreement_Identifier int,Party_Identifier bigint,Party_Role_Code varchar,Effective_Date datetime,Expiration_Date datetime,PRIMARY KEY(Agreement_Identifier ASC,Party_Identifier ASC,Party_Role_Code ASC,Effective_Date ASC),FOREIGN KEY(Agreement_Identifier)REFERENCES Agreement(Agreement_Identifier),FOREIGN KEY(Party_Identifier)REFERENCES Party(Party_Identifier),FOREIGN KEY(Party_Role_Code)REFERENCES Party_Role(Party_Role_Code));
CREATE TABLE Premium(Policy_Amount_Identifier bigint,PRIMARY KEY(Policy_Amount_Identifier ASC),FOREIGN KEY(Policy_Amount_Identifier)REFERENCES Policy_Amount(Policy_Amount_Identifier));
CREATE TABLE Catastrophe(Catastrophe_Identifier int,Catastrophe_Type_Code varchar,Catastrophe_Name varchar,Industry_Catastrophe_Code varchar,Company_Catastrophe_Code varchar,PRIMARY KEY(Catastrophe_Identifier ASC));